 "content": "def transform(grid):
    """Complete a broken rectangular outline: gaps on its long top/bottom and sides turn 2."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    marker = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    # The horizontal edges are the rows with the most outline markers.
    counts = [sum(v == marker for v in row) for row in grid]
    max_count = max(counts)
    edge_rows = [r for r, n in enumerate(counts) if n == max_count]
    top, bottom = min(edge_rows), max(edge_rows)
    edge_cols = [c for c in range(w) if grid[top][c] == marker or grid[bottom][c] == marker]
    left, right = min(edge_cols), max(edge_cols)
    for r in (top, bottom):
        for c in range(left, right + 1):
            if out[r][c] == bg:
                out[r][c] = 2
    for c in (left, right):
        for r in range(top, bottom + 1):
            if out[r][c] == bg:
                out[r][c] = 2
    return out
